const body = $input.first().json.body;
const msg = body?.message || {};
const chat = body?.chat || {};

const phone = (chat.wa_chatid || '')
  .replace('@s.whatsapp.net', '')
  .replace('@lid', '')
  .replace(/\D/g, '');

const text = (msg.text || msg.content || '').trim();
const pushName = chat.wa_contactName || msg.senderName || '';

// Identifica de qual instancia UazAPI (= qual studio) veio a mensagem.
// TODO: confirmar o nome exato do campo com um payload real da UazAPI antes de subir pra producao.
const instance = body?.instance || body?.owner || '';

return [{ json: { phone, text, pushName, instance } }];

const msg = $('Normalizar mensagem').first().json;
const studio = $('Resolver Studio').first().json;
const rows = $('Buscar sessÃ£o').all();
const hasSession = rows.length > 0 && rows[0].json?.phone;

const TIMEOUT_MINUTOS = 60;

let session;
if (hasSession) {
  const s = rows[0].json;
  const updatedAt = new Date(s.updated_at);
  const agora = new Date();
  const minutosPassados = (agora - updatedAt) / 1000 / 60;
  const expirou = minutosPassados > TIMEOUT_MINUTOS;

  if (expirou) {
    session = { intent: 'none', step: 'INIT', data: {}, history: [] };
  } else {
    session = {
      intent: s.intent || 'none',
      step: s.step || 'INIT',
      data: typeof s.data === 'string' ? JSON.parse(s.data) : (s.data || {}),
      history: typeof s.history === 'string' ? JSON.parse(s.history) : (s.history || [])
    };
  }
} else {
  session = { intent: 'none', step: 'INIT', data: {}, history: [] };
}

session.history.push({ role: 'user', content: msg.text });
if (session.history.length > 20) session.history = session.history.slice(-20);

return [{
  json: {
    phone: msg.phone,
    text: msg.text,
    pushName: msg.pushName,
    studioId: studio.studio_id,
    studioSlug: studio.studio_slug,
    studioName: studio.studio_name,
    intent: session.intent,
    step: session.step,
    sessionData: session.data,
    history: session.history
  }
}];

