// Pega o contexto do formatador correto via Switch
// O Enviar WA recebe de: Resposta direta, Formatar slots, Formatar confirmaÃ§Ã£o,
// Formatar agendamentos, Formatar cancelamento, Formatar remarcaÃ§Ã£o, Fallback
// Todos passam por Enviar WA â pegamos do nÃ³ de entrada dele

const possiveisContextos = [
  'Resposta direta',
  'Formatar slots',
  'Formatar confirmaÃ§Ã£o',
  'Formatar agendamentos',
  'Formatar cancelamento',
  'Formatar remarcaÃ§Ã£o',
  'Pedir dado faltante',
  'Fallback'
];

let sessionCtx = null;
for (const nome of possiveisContextos) {
  try {
    const candidate = $node[nome].json;
    if (candidate && candidate.phone) {
      sessionCtx = candidate;
      break;
    }
  } catch(e) { /* nÃ³ nÃ£o executou nessa rodada */ }
}

if (!sessionCtx) {
  throw new Error('NÃ£o encontrei contexto de sessÃ£o em nenhum formatador');
}

if (!sessionCtx.studioId) {
  throw new Error('Contexto de sessao sem studioId -- nao e seguro gravar bot_sessions sem studio resolvido');
}

const history = Array.isArray(sessionCtx.history) ? sessionCtx.history : [];
history.push({ role: 'assistant', content: sessionCtx.responseText || '' });
const trimmedHistory = history.slice(-20);

return [{
  json: {
    phone:       sessionCtx.phone || '',
    pushName:    sessionCtx.pushName || '',
    studioId:    sessionCtx.studioId,
    intent:      sessionCtx.intent || 'none',
    step:        sessionCtx.step || 'INIT',
    sessionData: JSON.stringify(typeof sessionCtx.sessionData === 'string' ? JSON.parse(sessionCtx.sessionData) : (sessionCtx.sessionData || {})),
    history:     JSON.stringify(trimmedHistory)
  }
}];

const ctx = $('Preparar prompt LLM1').first().json;
const response = $input.first().json;

let llmText = '';
try {
  llmText = response.choices[0].message.content;
} catch(e) {
  return [{
    json: {
      ...ctx,
      action: 'respond',
      response: 'Desculpa, tive um probleminha ð Pode repetir?',
      intent: ctx.intent,
      step: ctx.step,
      llmData: {}
    }
  }];
}

let parsed;
try {
  const clean = llmText.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  return [{
    json: {
      ...ctx,
      action: 'respond',
      response: llmText || 'Desculpa, pode repetir? ð',
      intent: ctx.intent,
      step: ctx.step,
      llmData: {}
    }
  }];
}

let mergedData = { ...ctx.sessionData, ...(parsed.data || {}) };
Object.keys(mergedData).forEach(k => {
  if (mergedData[k] === null || mergedData[k] === undefined || mergedData[k] === '') {
    delete mergedData[k];
  }
});

// Reseta dados ao concluir para nÃ£o contaminar prÃ³xima conversa
if (parsed.step === 'DONE') {
  mergedData = {};
}

return [{
  json: {
    phone: ctx.phone,
    pushName: ctx.pushName,
    text: ctx.text,
    history: ctx.history,
    studioId: ctx.studioId,
    studioSlug: ctx.studioSlug,
    studioName: ctx.studioName,
    action: parsed.action || 'respond',
    response: parsed.response || '',
    intent: parsed.intent || ctx.intent,
    step: parsed.step || ctx.step,
    llmData: mergedData
  }
}];

const ctx = $('Classificar resposta LLM1').first().json;
