let duplicata = null;
if (novaData) {
  duplicata = appointments.find(a => {
    const diffDias = Math.abs(new Date(a.date) - novaData) / (1000 * 60 * 60 * 24);
    return a.service_name && a.service_name.toLowerCase().includes(novoServico.replace(/_/g,' ').toLowerCase().split(' ')[0]) && diffDias < 7;
  });
}

return [{
  json: {
    ...ctx,
    duplicata: duplicata || null,
    temDuplicata: !!duplicata
  }
}];

